insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about Keibul Lamjao National Park:','केइबुल लामजाओ राष्ट्रीय उद्यान के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a floating national park, made up largely of ''phumdis'' on Loktak Lake.", "It is the last natural home of the sangai, the brow-antlered deer of Manipur.", "It has been notified as a tiger reserve."], "statements_hi": ["यह एक तैरता राष्ट्रीय उद्यान है, जो मुख्यतः लोकटक झील के ''फुमदी'' से बना है।", "यह संगाई, यानी मणिपुर के भौंह-सींग वाले हिरण, का अंतिम प्राकृतिक आवास है।", "इसे बाघ अभयारण्य (tiger reserve) के रूप में अधिसूचित किया गया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Phumdis are floating mats of vegetation, soil and organic matter; the park''s thickest phumdis carry the weight of the sangai, which walks on them with splayed hooves. The sangai, Manipur''s State animal, was once thought extinct and survives in the wild only here, which makes it vulnerable to any change in the lake -- such as the rise in water level caused by the Ithai barrage, which thins the phumdis. Statement 3 is wrong: Keibul Lamjao is not a tiger reserve; its flagship is the sangai.','कथन 1 और 2 सही हैं। फुमदी वनस्पति, मिट्टी और जैविक पदार्थ की तैरती परतें हैं; उद्यान की सबसे मोटी फुमदी संगाई का भार उठाती हैं, जो फैले खुरों से उन पर चलता है। मणिपुर का राज्य पशु संगाई कभी विलुप्त माना गया था और जंगल में केवल यहीं बचा है, इसलिए झील में कोई भी बदलाव इसके लिए खतरा है, जैसे इथाई बैराज से बढ़ा जल-स्तर, जो फुमदी को पतला कर देता है। कथन 3 गलत है: केइबुल लामजाओ बाघ अभयारण्य नहीं है; इसकी पहचान संगाई है।','env-keibul-lamjao-sangai','original_pattern_matched','Manipur Forest Department -- Keibul Lamjao National Park; IUCN Red List of Threatened Species: Rucervus eldii eldii.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about dolphins in India:','भारत में डॉल्फ़िनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Ganges river dolphin is India''s National Aquatic Animal.", "Irrawaddy dolphins are found in Chilika Lake.", "The Vikramshila Gangetic Dolphin Sanctuary is in Assam."], "statements_hi": ["गंगा नदी डॉल्फ़िन भारत का राष्ट्रीय जलीय जीव है।", "इरावदी डॉल्फ़िन चिल्का झील में पाई जाती हैं।", "विक्रमशिला गांगेय डॉल्फ़िन अभयारण्य असम में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Ganges river dolphin, declared the National Aquatic Animal in 2009, is nearly blind and hunts by echolocation in muddy water; it is Endangered, threatened by dams and barrages that fragment rivers, sand mining and fishing nets. Project Dolphin (2020) aims at its conservation, and a first range-wide estimate was released in 2025. Chilika, Asia''s largest brackish-water lagoon, holds a small population of the Irrawaddy dolphin, a coastal and estuarine species. Statement 3 is wrong: the Vikramshila Gangetic Dolphin Sanctuary is on the Ganga near Bhagalpur in Bihar.','कथन 1 और 2 सही हैं। 2009 में राष्ट्रीय जलीय जीव घोषित गंगा नदी डॉल्फ़िन लगभग अंधी होती है और गंदले पानी में प्रतिध्वनि-निर्धारण से शिकार करती है; यह संकटग्रस्त है, और इसे नदियों को टुकड़ों में बाँटने वाले बाँधों और बैराजों, बालू-खनन और मछली के जालों से खतरा है। प्रोजेक्ट डॉल्फ़िन (2020) इसके संरक्षण के लिए है, और 2025 में इसका पहला व्यापक आकलन जारी हुआ। एशिया के सबसे बड़े खारे पानी के लैगून चिल्का में इरावदी डॉल्फ़िन की छोटी आबादी है, जो तटीय और ज्वारनदमुखी प्रजाति है। कथन 3 गलत है: विक्रमशिला गांगेय डॉल्फ़िन अभयारण्य बिहार में भागलपुर के पास गंगा पर है।','env-india-dolphins','original_pattern_matched','Ministry of Environment, Forest and Climate Change -- Project Dolphin and the river dolphin estimation (2025); IUCN Red List of Threatened Species: Platanista gangetica, Orcaella brevirostris.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about international cooperation on big cats:','बड़ी बिल्लियों (big cats) पर अंतरराष्ट्रीय सहयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Global Tiger Forum has its secretariat in New Delhi.", "The International Big Cat Alliance, launched by India in 2023, covers only the big cats that are found in India.", "The ''Tx2'' goal of doubling the number of wild tigers was adopted at the St Petersburg Tiger Summit in 2010."], "statements_hi": ["वैश्विक बाघ मंच (Global Tiger Forum) का सचिवालय नई दिल्ली में है।", "भारत द्वारा 2023 में शुरू किया गया अंतरराष्ट्रीय बिग कैट गठबंधन केवल उन्हीं बड़ी बिल्लियों को शामिल करता है जो भारत में पाई जाती हैं।", "जंगली बाघों की संख्या दोगुनी करने का ''Tx2'' लक्ष्य 2010 में सेंट पीटर्सबर्ग बाघ शिखर सम्मेलन में अपनाया गया था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The Global Tiger Forum, an intergovernmental body of tiger-range countries, is based in New Delhi. At St Petersburg in 2010 the 13 tiger-range countries adopted the goal of doubling wild tigers by 2022; India, which holds about three-quarters of the world''s wild tigers, is among the few that met it. Statement 2 is wrong: the International Big Cat Alliance, launched at the 50-year commemoration of Project Tiger in 2023 and headquartered in India, covers seven big cats -- tiger, lion, leopard, snow leopard, cheetah, jaguar and puma -- the last two found only in the Americas.','कथन 1 और 3 सही हैं। बाघ-क्षेत्र वाले देशों का अंतर-सरकारी निकाय वैश्विक बाघ मंच नई दिल्ली में स्थित है। 2010 में सेंट पीटर्सबर्ग में 13 बाघ-क्षेत्र देशों ने 2022 तक जंगली बाघों को दोगुना करने का लक्ष्य अपनाया; विश्व के लगभग तीन-चौथाई जंगली बाघों वाला भारत उन गिने-चुने देशों में है जिन्होंने इसे पूरा किया। कथन 2 गलत है: 2023 में प्रोजेक्ट टाइगर के 50 वर्ष पूरे होने पर शुरू हुआ और भारत में मुख्यालय वाला अंतरराष्ट्रीय बिग कैट गठबंधन सात बड़ी बिल्लियों को शामिल करता है: बाघ, शेर, तेंदुआ, हिम तेंदुआ, चीता, जगुआर और प्यूमा; अंतिम दो केवल अमेरिका महाद्वीपों में मिलते हैं।','env-big-cat-cooperation','original_pattern_matched','Global Tiger Forum; St Petersburg Declaration on Tiger Conservation (2010); Ministry of Environment, Forest and Climate Change -- International Big Cat Alliance (2023).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about India''s natural World Heritage Sites:','भारत के प्राकृतिक विश्व धरोहर स्थलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Khangchendzonga National Park was India''s first ''mixed'' World Heritage Site, inscribed for both natural and cultural values.", "Manas Wildlife Sanctuary was placed on the List of World Heritage in Danger and later removed from it.", "Nanda Devi National Park and the Valley of Flowers National Park together form a single World Heritage Site."], "statements_hi": ["कंचनजंगा राष्ट्रीय उद्यान भारत का पहला ''मिश्रित'' विश्व धरोहर स्थल था, जिसे प्राकृतिक और सांस्कृतिक, दोनों मूल्यों के लिए शामिल किया गया।", "मानस वन्यजीव अभयारण्य को संकटग्रस्त विश्व धरोहर की सूची में रखा गया था और बाद में उससे हटा दिया गया।", "नंदा देवी राष्ट्रीय उद्यान और फूलों की घाटी राष्ट्रीय उद्यान मिलकर एक ही विश्व धरोहर स्थल बनाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Khangchendzonga in Sikkim was inscribed in 2016 for its glaciers, forests and wildlife and for the sacred meaning of the mountain to the people of Sikkim. Manas, on the Bhutan border in Assam, was put on the danger list in 1992 after its rhinos and infrastructure were destroyed during an insurgency and was taken off in 2011 after the populations recovered, with rhinos brought back from Kaziranga and Pobitora. Nanda Devi was inscribed in 1988, and the Valley of Flowers was added to it in 2005 as a single site in Uttarakhand.','तीनों कथन सही हैं। सिक्किम का कंचनजंगा 2016 में अपने हिमनदों, वनों और वन्यजीवों के लिए और सिक्किम के लोगों के लिए पर्वत के पवित्र अर्थ के लिए शामिल हुआ। असम में भूटान सीमा पर स्थित मानस को 1992 में संकट-सूची में रखा गया, जब एक उग्रवाद के दौरान उसके गैंडे और ढाँचा नष्ट हो गए, और 2011 में आबादियाँ उबरने के बाद, काज़ीरंगा और पोबितोरा से गैंडे वापस लाकर, उसे सूची से हटाया गया। नंदा देवी 1988 में शामिल हुआ, और 2005 में फूलों की घाटी को उसके साथ उत्तराखंड के एक ही स्थल के रूप में जोड़ा गया।','env-india-natural-whs','original_pattern_matched','UNESCO World Heritage Centre -- Khangchendzonga National Park (2016), Manas Wildlife Sanctuary, Nanda Devi and Valley of Flowers National Parks.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the protected areas of the Andaman and Nicobar Islands:','अंडमान और निकोबार द्वीपसमूह के संरक्षित क्षेत्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Great Nicobar is a biosphere reserve.", "Campbell Bay and Galathea National Parks lie in the Andaman group of islands.", "The Narcondam hornbill is found throughout the Andaman Islands."], "statements_hi": ["ग्रेट निकोबार एक जैवमंडल आरक्षित क्षेत्र (biosphere reserve) है।", "कैम्पबेल बे और गैलाथिया राष्ट्रीय उद्यान अंडमान द्वीप समूह में स्थित हैं।", "नारकोंडम धनेश पूरे अंडमान द्वीपसमूह में पाया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the Great Nicobar Biosphere Reserve, declared in 1989 and part of UNESCO''s World Network since 2013, protects tropical wet evergreen forest, mangroves and nesting beaches of the leatherback turtle. Statement 2 is wrong: Campbell Bay and Galathea National Parks are the two core zones of that reserve, on Great Nicobar in the Nicobar group, not the Andamans. Statement 3 is wrong: the Narcondam hornbill is endemic to the tiny volcanic island of Narcondam, about 7 sq km, which makes it one of the most restricted birds in India.','केवल कथन 1 सही है: 1989 में घोषित और 2013 से UNESCO के विश्व नेटवर्क का हिस्सा ग्रेट निकोबार जैवमंडल आरक्षित क्षेत्र उष्णकटिबंधीय आर्द्र सदाबहार वन, मैंग्रोव और लेदरबैक कछुए के घोंसला-तटों की रक्षा करता है। कथन 2 गलत है: कैम्पबेल बे और गैलाथिया राष्ट्रीय उद्यान उसी आरक्षित क्षेत्र के दो कोर क्षेत्र हैं, जो निकोबार समूह के ग्रेट निकोबार पर हैं, अंडमान में नहीं। कथन 3 गलत है: नारकोंडम धनेश लगभग 7 वर्ग किमी के छोटे ज्वालामुखीय द्वीप नारकोंडम का स्थानिक है, जो इसे भारत के सबसे सीमित क्षेत्र वाले पक्षियों में बनाता है।','env-andaman-nicobar-protected-areas','original_pattern_matched','UNESCO Man and the Biosphere Programme -- Great Nicobar Biosphere Reserve; IUCN Red List of Threatened Species: Rhyticeros narcondami; Andaman and Nicobar Forest Department.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about captive elephants under the Wild Life (Protection) Act:','वन्यजीव (संरक्षण) अधिनियम के तहत बंदी हाथियों (captive elephants) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The 2022 amendment allows a person holding a valid ownership certificate to transfer a captive elephant for a religious or any other purpose, subject to conditions.", "The Asian elephant is listed in Schedule I of the Act.", "A person keeping a captive elephant must hold an ownership certificate issued by the Chief Wild Life Warden."], "statements_hi": ["2022 का संशोधन वैध स्वामित्व प्रमाणपत्र रखने वाले व्यक्ति को शर्तों के अधीन किसी बंदी हाथी को धार्मिक या किसी अन्य उद्देश्य के लिए हस्तांतरित करने की अनुमति देता है।", "एशियाई हाथी अधिनियम की अनुसूची I में सूचीबद्ध है।", "बंदी हाथी रखने वाले व्यक्ति के पास मुख्य वन्यजीव वार्डन द्वारा जारी स्वामित्व प्रमाणपत्र होना चाहिए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The 2022 amendment carved out an exception in the ban on transferring Schedule I animals, allowing captive elephants to be transferred or moved by certificate holders; the Captive Elephant (Transfer or Transport) Rules, 2024 lay down the conditions, such as health checks and a genetic profile. Critics argued that the exception could launder wild-caught elephants into temples and private hands, which is why the certificate and registration requirements matter. A student who expects one statement to be false will pick ''Only two''.','तीनों कथन सही हैं। 2022 के संशोधन ने अनुसूची I के जंतुओं के हस्तांतरण पर रोक में एक अपवाद बनाया, जिससे प्रमाणपत्रधारी बंदी हाथियों का हस्तांतरण या परिवहन कर सकते हैं; बंदी हाथी (हस्तांतरण या परिवहन) नियम, 2024 स्वास्थ्य जाँच और आनुवंशिक प्रोफ़ाइल जैसी शर्तें तय करते हैं। आलोचकों का तर्क था कि यह अपवाद जंगल से पकड़े गए हाथियों को मंदिरों और निजी हाथों में ''वैध'' बनाने का रास्ता बन सकता है, इसीलिए प्रमाणपत्र और पंजीकरण की अपेक्षाएँ महत्त्वपूर्ण हैं। जो विद्यार्थी मानता है कि एक कथन गलत होगा ही, वह ''केवल दो'' चुन लेगा।','env-captive-elephants-transfer','original_pattern_matched','Wild Life (Protection) Act, 1972, as amended in 2022, sections 42 and 43; Captive Elephant (Transfer or Transport) Rules, 2024.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about India''s protected area network:','भारत के संरक्षित क्षेत्र नेटवर्क के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["National parks, wildlife sanctuaries, conservation reserves and community reserves together cover about 5 per cent of India''s geographical area.", "India has more national parks than wildlife sanctuaries.", "Conservation reserves are declared by the Central Government."], "statements_hi": ["राष्ट्रीय उद्यान, वन्यजीव अभयारण्य, संरक्षण आरक्षित क्षेत्र और सामुदायिक आरक्षित क्षेत्र मिलकर भारत के भौगोलिक क्षेत्र का लगभग 5 प्रतिशत भाग घेरते हैं।", "भारत में वन्यजीव अभयारण्यों से अधिक राष्ट्रीय उद्यान हैं।", "संरक्षण आरक्षित क्षेत्र केंद्र सरकार द्वारा घोषित किए जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the network of about a thousand protected areas covers a little over 5 per cent of the country, well short of the 30 per cent ''30x30'' goal of the global biodiversity framework, which also counts other effective area-based measures. Statement 2 is reversed: India has a little over a hundred national parks but more than five hundred wildlife sanctuaries. Statement 3 is wrong: conservation reserves, usually government land next to protected areas, are declared by the State Government after consulting the local communities, under section 36A added in 2002.','केवल कथन 1 सही है: लगभग एक हज़ार संरक्षित क्षेत्रों का नेटवर्क देश के 5 प्रतिशत से कुछ अधिक भाग पर है, जो वैश्विक जैव विविधता ढाँचे के 30 प्रतिशत के ''30x30'' लक्ष्य से बहुत कम है; वह लक्ष्य दूसरे प्रभावी क्षेत्र-आधारित उपायों को भी गिनता है। कथन 2 उलटा है: भारत में सौ से कुछ अधिक राष्ट्रीय उद्यान हैं, पर पाँच सौ से अधिक वन्यजीव अभयारण्य। कथन 3 गलत है: संरक्षण आरक्षित क्षेत्र, जो प्रायः संरक्षित क्षेत्रों से सटी सरकारी भूमि होते हैं, 2002 में जोड़ी गई धारा 36A के तहत स्थानीय समुदायों से परामर्श के बाद राज्य सरकार द्वारा घोषित किए जाते हैं।','env-protected-area-network','original_pattern_matched','Wildlife Institute of India, ENVIS Centre on Wildlife and Protected Areas -- National Wildlife Database; Wild Life (Protection) Act, 1972, as amended in 2022, section 36A.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the conservation of the greater one-horned rhinoceros in Assam:','असम में एक सींग वाले बड़े गैंडे के संरक्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["''Indian Rhino Vision 2020'' aimed to raise Assam''s wild rhino population to about 3,000, spread over several protected areas.", "Pobitora Wildlife Sanctuary has one of the highest densities of rhinos in the world.", "Rhinos have been translocated from Kaziranga and Pobitora to Manas."], "statements_hi": ["''इंडियन राइनो विज़न 2020'' का लक्ष्य असम की जंगली गैंडा आबादी को कई संरक्षित क्षेत्रों में फैलाकर लगभग 3,000 तक पहुँचाना था।", "पोबितोरा वन्यजीव अभयारण्य में गैंडों का घनत्व विश्व में सबसे अधिक में से एक है।", "काज़ीरंगा और पोबितोरा से गैंडों को मानस में स्थानांतरित किया गया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. With most of Assam''s rhinos in Kaziranga, a single epidemic, flood or poaching wave could be disastrous, so Indian Rhino Vision 2020 -- a partnership of the Assam government, WWF-India and others -- set out to spread them across seven protected areas. Pobitora, a small sanctuary near Guwahati, is so crowded with rhinos that it served as a source population, and translocations brought rhinos back to Manas, where they had been wiped out during the insurgency. Anti-poaching has since cut rhino killings in Assam to very low levels.','तीनों कथन सही हैं। असम के अधिकांश गैंडे काज़ीरंगा में होने के कारण एक ही महामारी, बाढ़ या शिकार की लहर विनाशकारी हो सकती थी, इसलिए असम सरकार, WWF-India और दूसरों की साझेदारी ''इंडियन राइनो विज़न 2020'' ने उन्हें सात संरक्षित क्षेत्रों में फैलाने का लक्ष्य रखा। गुवाहाटी के पास का छोटा अभयारण्य पोबितोरा गैंडों से इतना भरा है कि वह स्रोत-आबादी बना, और स्थानांतरण से गैंडे मानस में लौटे, जहाँ उग्रवाद के दौरान वे मिट गए थे। तब से शिकार-रोधी उपायों ने असम में गैंडों की हत्या को बहुत कम कर दिया है।','env-indian-rhino-vision-2020','original_pattern_matched','Assam Forest Department and WWF-India -- Indian Rhino Vision 2020; IUCN SSC Asian Rhino Specialist Group.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the protection of sea turtles in India:','भारत में समुद्री कछुओं के संरक्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["''Operation Olivia'', to protect olive ridley turtles off the Odisha coast, is run by the Indian Navy.", "Turtle excluder devices fitted to trawl nets allow trapped turtles to escape.", "Sea turtles are listed in a lower Schedule of the Wild Life (Protection) Act that allows their regulated capture."], "statements_hi": ["ओडिशा तट के पास ऑलिव रिडले कछुओं की रक्षा के लिए ''ऑपरेशन ओलिविया'' भारतीय नौसेना चलाती है।", "ट्रॉल जालों में लगाए गए कछुआ निष्कासक उपकरण (turtle excluder devices) फँसे कछुओं को निकल जाने देते हैं।", "समुद्री कछुए वन्यजीव (संरक्षण) अधिनियम की एक निचली अनुसूची में सूचीबद्ध हैं, जो उनके नियंत्रित शिकार की अनुमति देती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: a turtle excluder device is a grid in the trawl net that lets fish pass into the bag but deflects turtles out through an opening, and its use is required in some States'' waters during the nesting season. Statement 1 is wrong: Operation Olivia is run every nesting season by the Indian Coast Guard, which patrols the waters off Gahirmatha and the Rushikulya and Devi river mouths against illegal trawling. Statement 3 is wrong: all five sea turtle species found in Indian waters are in Schedule I, the highest protection.','केवल कथन 2 सही है: कछुआ निष्कासक उपकरण ट्रॉल जाल में लगी एक जाली है, जो मछलियों को थैले में जाने देती है पर कछुओं को एक छेद से बाहर मोड़ देती है, और कुछ राज्यों के जल में घोंसले के मौसम में इसका उपयोग अनिवार्य है। कथन 1 गलत है: ऑपरेशन ओलिविया हर घोंसला-मौसम में भारतीय तटरक्षक बल चलाता है, जो अवैध ट्रॉलिंग के विरुद्ध गहिरमाथा और रुशिकुल्या तथा देवी नदी मुहानों के पास के जल में गश्त करता है। कथन 3 गलत है: भारतीय जल में मिलने वाली समुद्री कछुओं की पाँचों प्रजातियाँ अनुसूची I में हैं, जो सर्वोच्च संरक्षण है।','env-sea-turtle-protection-measures','original_pattern_matched','Indian Coast Guard -- Operation Olivia; Wild Life (Protection) Act, 1972, as amended in 2022, Schedule I; CMFRI -- turtle excluder devices.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the conservation of wetlands in India:','भारत में आर्द्रभूमियों के संरक्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Wetlands (Conservation and Management) Rules, 2017 were framed under the Wild Life (Protection) Act, 1972.", "Under these Rules, wetlands can be notified only by the Central Government.", "The ''Amrit Dharohar'' scheme, announced in 2023, aims to conserve heritage buildings along India''s rivers."], "statements_hi": ["आर्द्रभूमि (संरक्षण और प्रबंधन) नियम, 2017 वन्यजीव (संरक्षण) अधिनियम, 1972 के तहत बनाए गए।", "इन नियमों के तहत आर्द्रभूमियों को केवल केंद्र सरकार अधिसूचित कर सकती है।", "2023 में घोषित ''अमृत धरोहर'' योजना का लक्ष्य भारत की नदियों के किनारे की धरोहर इमारतों का संरक्षण है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The 2017 Rules were framed under the Environment (Protection) Act, 1986, not the Wild Life Act, and replaced the Rules of 2010; they give the identification and notification of wetlands to the State Wetlands Authority of each State and Union Territory, not to the Centre, and prohibit activities such as encroachment, dumping of waste and conversion for non-wetland use in notified wetlands. Statement 3 is a trap set by the name (''dharohar'' means heritage): Amrit Dharohar, announced in the Union Budget 2023-24 and launched on World Environment Day that year, is a wetland scheme that promotes community-based conservation, eco-tourism and livelihoods around Ramsar sites, whose number India has expanded rapidly since 2019.','कोई भी कथन सही नहीं है। 2017 के नियम वन्यजीव अधिनियम के नहीं, पर्यावरण (संरक्षण) अधिनियम, 1986 के तहत बने और उन्होंने 2010 के नियमों की जगह ली; ये आर्द्रभूमियों की पहचान और अधिसूचना केंद्र को नहीं, हर राज्य और केंद्रशासित प्रदेश के राज्य आर्द्रभूमि प्राधिकरण को सौंपते हैं और अधिसूचित आर्द्रभूमियों में अतिक्रमण, कचरा डालने और गैर-आर्द्रभूमि उपयोग के लिए बदलने जैसी गतिविधियों पर रोक लगाते हैं। कथन 3 नाम से बिछाया गया जाल है (''धरोहर'' का अर्थ विरासत है): केंद्रीय बजट 2023-24 में घोषित और उसी वर्ष विश्व पर्यावरण दिवस पर शुरू हुई अमृत धरोहर एक आर्द्रभूमि योजना है, जो रामसर स्थलों के आसपास समुदाय-आधारित संरक्षण, पर्यावरण-पर्यटन और आजीविका को बढ़ावा देती है; भारत ने 2019 से रामसर स्थलों की संख्या तेज़ी से बढ़ाई है।','env-wetland-rules-amrit-dharohar','original_pattern_matched','Wetlands (Conservation and Management) Rules, 2017; Ministry of Environment, Forest and Climate Change -- Amrit Dharohar (2023).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Simlipal Tiger Reserve is in West Bengal.", "Kawal Tiger Reserve is in Maharashtra.", "Dampa Tiger Reserve is in Meghalaya."], "statements_hi": ["सिमलीपाल बाघ अभयारण्य पश्चिम बंगाल में है।", "कवाल बाघ अभयारण्य महाराष्ट्र में है।", "डम्पा बाघ अभयारण्य मेघालय में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct; each places a tiger reserve in a neighbouring State. Simlipal is in Mayurbhanj district of Odisha, known for its melanistic (''black'') tigers; Kawal is in Telangana, on the Godavari side of the Deccan, linked by forests to Tadoba in Maharashtra; and Dampa is in western Mizoram, on the Bangladesh border. The trap is plausibility -- each wrong State shares a border or a forest landscape with the right one.','कोई भी कथन सही नहीं है; हर कथन किसी बाघ अभयारण्य को पड़ोसी राज्य में रख देता है। सिमलीपाल ओडिशा के मयूरभंज ज़िले में है, जो अपने मेलानिस्टिक (''काले'') बाघों के लिए जाना जाता है; कवाल तेलंगाना में दक्कन की गोदावरी ओर है, जो वनों के ज़रिए महाराष्ट्र के ताडोबा से जुड़ा है; और डम्पा पश्चिमी मिज़ोरम में बांग्लादेश सीमा पर है। जाल विश्वसनीयता में है: हर गलत राज्य सही राज्य से सीमा या वन-भू-दृश्य साझा करता है।','env-tiger-reserve-locations','original_pattern_matched','National Tiger Conservation Authority -- list of tiger reserves of India.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about mangrove conservation:','मैंग्रोव संरक्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The MISHTI scheme, launched in 2023, aims to plant mangroves along India''s coasts and on salt pans.", "India has stayed out of the Mangrove Alliance for Climate, launched at COP27.", "Among the States, Gujarat has the largest mangrove cover."], "statements_hi": ["2023 में शुरू की गई MISHTI योजना का लक्ष्य भारत के तटों और नमक के खेतों (salt pans) पर मैंग्रोव लगाना है।", "भारत COP27 में शुरू किए गए ''मैंग्रोव एलायंस फ़ॉर क्लाइमेट'' से बाहर रहा है।", "राज्यों में गुजरात का मैंग्रोव आवरण सबसे बड़ा है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. MISHTI (Mangrove Initiative for Shoreline Habitats and Tangible Incomes), announced in the Union Budget 2023-24, funds mangrove planting by pooling money from rural employment schemes, CAMPA funds and other sources. Statement 2 is wrong: the Mangrove Alliance for Climate, led by the UAE and Indonesia, was launched at COP27 in 2022, and India joined it. Statement 3 is wrong: in the Forest Survey of India''s reports, West Bengal (the Sundarbans) has the largest mangrove cover, followed by Gujarat, where mangroves line the Gulf of Kutch and the Gulf of Khambhat, and then the Andaman and Nicobar Islands.','केवल कथन 1 सही है। केंद्रीय बजट 2023-24 में घोषित MISHTI (Mangrove Initiative for Shoreline Habitats and Tangible Incomes) अन्य योजनाओं और CAMPA निधि के समन्वय से मैंग्रोव रोपण को धन देती है। कथन 2 गलत है: UAE और इंडोनेशिया के नेतृत्व वाला मैंग्रोव एलायंस फ़ॉर क्लाइमेट 2022 में COP27 में शुरू हुआ, और भारत उसमें शामिल हुआ। कथन 3 गलत है: भारतीय वन सर्वेक्षण की रिपोर्टों में सबसे बड़ा मैंग्रोव आवरण पश्चिम बंगाल (सुंदरबन) का है, उसके बाद गुजरात का, जहाँ कच्छ की खाड़ी और खंभात की खाड़ी के किनारे मैंग्रोव हैं, और फिर अंडमान और निकोबार द्वीपसमूह का।','env-mangrove-initiatives','original_pattern_matched','Ministry of Environment, Forest and Climate Change -- MISHTI (2023); Mangrove Alliance for Climate (COP27); Forest Survey of India -- India State of Forest Report 2023 (mangrove cover).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about coral reefs in India:','भारत में प्रवाल भित्तियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The main coral reef areas of India are the Gulf of Mannar, the Gulf of Kutch, Lakshadweep and the Andaman and Nicobar Islands.", "Reef-building corals are listed in Schedule I of the Wild Life (Protection) Act.", "Coral mining is permitted in India for making lime, subject to a licence."], "statements_hi": ["भारत के मुख्य प्रवाल भित्ति क्षेत्र मन्नार की खाड़ी, कच्छ की खाड़ी, लक्षद्वीप और अंडमान तथा निकोबार द्वीपसमूह हैं।", "भित्ति बनाने वाले प्रवाल वन्यजीव (संरक्षण) अधिनियम की अनुसूची I में सूचीबद्ध हैं।", "भारत में चूना बनाने के लिए लाइसेंस के अधीन प्रवाल-खनन की अनुमति है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. India''s reefs are fringing reefs in the Gulf of Mannar and the Gulf of Kutch, atolls in Lakshadweep, and fringing and barrier reefs around the Andaman and Nicobar Islands. Reef-building corals, black corals and sea fans are in Schedule I, so collecting or trading them is an offence. Statement 3 is wrong: coral mining, once carried out on a large scale in the Gulf of Mannar for lime and construction, is banned; it destroyed several small islands there, which are now being restored.','कथन 1 और 2 सही हैं। भारत की भित्तियाँ मन्नार की खाड़ी और कच्छ की खाड़ी में तटीय (fringing) भित्तियाँ, लक्षद्वीप में एटॉल, और अंडमान तथा निकोबार के आसपास तटीय और अवरोधक (barrier) भित्तियाँ हैं। भित्ति बनाने वाले प्रवाल, काले प्रवाल और सी-फ़ैन अनुसूची I में हैं, इसलिए उन्हें इकट्ठा करना या उनका व्यापार अपराध है। कथन 3 गलत है: प्रवाल-खनन, जो कभी मन्नार की खाड़ी में चूने और निर्माण के लिए बड़े पैमाने पर होता था, प्रतिबंधित है; इसने वहाँ कई छोटे द्वीपों को नष्ट कर दिया, जिन्हें अब पुनर्स्थापित किया जा रहा है।','env-coral-reefs-india','original_pattern_matched','Zoological Survey of India -- coral reefs of India; Wild Life (Protection) Act, 1972, as amended in 2022, Schedule I; Coastal Regulation Zone Notification, 2019.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about ex situ conservation:','बाह्य-स्थाने (ex situ) संरक्षण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Zoos and botanical gardens are forms of ex situ conservation.", "In cryopreservation, gametes and seeds can be stored for long periods at about -196 degrees Celsius in liquid nitrogen.", "Biosphere reserves are a form of ex situ conservation.", "The Svalbard Global Seed Vault, which stores duplicate seed samples from gene banks around the world, is in Norway."], "statements_hi": ["चिड़ियाघर और वनस्पति उद्यान बाह्य-स्थाने संरक्षण के रूप हैं।", "निम्नताप-परिरक्षण (cryopreservation) में युग्मकों और बीजों को द्रव नाइट्रोजन में लगभग -196 डिग्री सेल्सियस पर लंबे समय तक संग्रहीत किया जा सकता है।", "जैवमंडल आरक्षित क्षेत्र बाह्य-स्थाने संरक्षण का एक रूप हैं।", "विश्व भर के जीन बैंकों के बीज-नमूनों की प्रतियाँ रखने वाला स्वालबार्ड ग्लोबल सीड वॉल्ट नॉर्वे में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 4 are correct. Ex situ conservation protects species outside their natural habitat -- zoos, botanical gardens, seed and gene banks, and captive breeding -- often as a last resort for species that cannot survive in the wild for now. Cryopreservation in liquid nitrogen keeps seeds, pollen, sperm and eggs viable for many years. The Svalbard vault, dug into a mountain on an Arctic island, is a back-up for the world''s gene banks; India''s own National Gene Bank is at the ICAR-National Bureau of Plant Genetic Resources in New Delhi. Statement 3 is wrong: biosphere reserves, like national parks and sacred groves, conserve species in their natural surroundings, which is in situ conservation.','कथन 1, 2 और 4 सही हैं। बाह्य-स्थाने संरक्षण प्रजातियों को उनके प्राकृतिक आवास के बाहर बचाता है, जैसे चिड़ियाघर, वनस्पति उद्यान, बीज और जीन बैंक, और बंदी प्रजनन; यह प्रायः उन प्रजातियों के लिए अंतिम उपाय है जो अभी जंगल में नहीं बच सकतीं। द्रव नाइट्रोजन में निम्नताप-परिरक्षण बीजों, परागकणों, शुक्राणुओं और अंडों को कई वर्षों तक जीवित रखता है। आर्कटिक के एक द्वीप पर पहाड़ में खोदा गया स्वालबार्ड वॉल्ट विश्व के जीन बैंकों का बैक-अप है; भारत का अपना राष्ट्रीय जीन बैंक नई दिल्ली में ICAR-राष्ट्रीय पादप आनुवंशिक संसाधन ब्यूरो में है। कथन 3 गलत है: राष्ट्रीय उद्यानों और पवित्र उपवनों की तरह जैवमंडल आरक्षित क्षेत्र प्रजातियों को उनके प्राकृतिक परिवेश में बचाते हैं, जो स्व-स्थाने (in situ) संरक्षण है।','env-ex-situ-conservation','original_pattern_matched','NCERT Class XII, Biology -- Biodiversity and Conservation (in situ and ex situ conservation); Crop Trust -- Svalbard Global Seed Vault; ICAR-NBPGR -- National Genebank.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about Kanha Tiger Reserve:','कान्हा बाघ अभयारण्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The hard-ground barasingha was saved from near-extinction in Kanha.", "Kanha Tiger Reserve is in Maharashtra.", "The barasingha of Kanha lives mainly in swamps."], "statements_hi": ["कठोर-भूमि बारहसिंगा को कान्हा में लगभग विलुप्ति से बचाया गया।", "कान्हा बाघ अभयारण्य महाराष्ट्र में है।", "कान्हा का बारहसिंगा मुख्य रूप से दलदलों में रहता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the population of this subspecies of swamp deer fell to about 66 animals around 1970 and was rebuilt in Kanha through protection, relocation of villages from its meadows and management of the grasslands; animals have since been reintroduced elsewhere, such as Satpura. Statement 2 is wrong: Kanha is in the Maikal hills of Madhya Pradesh, whose State animal is the barasingha. Statement 3 is the trap: despite the name ''swamp deer'', the Kanha subspecies (Rucervus duvaucelii branderi) is adapted to hard ground and lives in open grassy meadows, unlike the swamp-dwelling subspecies of the terai and Assam.','केवल कथन 1 सही है: दलदली हिरण की इस उप-प्रजाति की आबादी लगभग 1970 तक करीब 66 तक गिर गई थी और कान्हा में संरक्षण, इसके घास के मैदानों से गाँवों के स्थानांतरण और घास के मैदानों के प्रबंधन से फिर बढ़ाई गई; तब से सतपुड़ा जैसे दूसरे स्थानों पर भी इसे फिर बसाया गया है। कथन 2 गलत है: कान्हा मध्य प्रदेश की मैकल पहाड़ियों में है, जिसका राज्य पशु बारहसिंगा है। कथन 3 जाल है: ''दलदली हिरण'' नाम के बावजूद कान्हा की उप-प्रजाति (Rucervus duvaucelii branderi) कठोर भूमि के अनुकूल है और खुले घास के मैदानों में रहती है, तराई और असम की दलदल में रहने वाली उप-प्रजातियों के विपरीत।','env-kanha-barasingha','original_pattern_matched','Madhya Pradesh Forest Department -- Kanha Tiger Reserve (barasingha recovery); IUCN Red List: Rucervus duvaucelii.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','medium','Consider the following statements about the Sundarbans:','सुंदरबन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Indian Sundarbans are at the same time a World Heritage Site, a tiger reserve, a biosphere reserve and a Ramsar site.", "Sundarbans tigers regularly swim between islands.", "The Sundarbans mangroves lie on the delta of the Mahanadi."], "statements_hi": ["भारतीय सुंदरबन एक साथ विश्व धरोहर स्थल, बाघ अभयारण्य, जैवमंडल आरक्षित क्षेत्र और रामसर स्थल हैं।", "सुंदरबन के बाघ नियमित रूप से द्वीपों के बीच तैरते हैं।", "सुंदरबन के मैंग्रोव महानदी के डेल्टा पर स्थित हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Sundarbans National Park became a World Heritage Site in 1987, the tiger reserve dates from 1973, the biosphere reserve joined UNESCO''s network in 2001, and the Indian Sundarbans became a Ramsar site in 2019 -- one of the few places with all four labels. Its tigers live in a tidal maze of creeks and islands, swim across channels and have adapted to a diet that includes fish and crabs. Statement 3 is wrong: the Sundarbans lie on the delta of the Ganga, Brahmaputra and Meghna, shared by India and Bangladesh; the Mahanadi delta holds Bhitarkanika.','कथन 1 और 2 सही हैं। सुंदरबन राष्ट्रीय उद्यान 1987 में विश्व धरोहर स्थल बना, बाघ अभयारण्य 1973 से है, जैवमंडल आरक्षित क्षेत्र 2001 में UNESCO के नेटवर्क में शामिल हुआ, और भारतीय सुंदरबन 2019 में रामसर स्थल बना; यह उन गिने-चुने स्थानों में है जिनके पास चारों पहचानें हैं। इसके बाघ खाड़ियों और द्वीपों की ज्वारीय भूल-भुलैया में रहते हैं, नालों को तैरकर पार करते हैं और मछली तथा केकड़ों वाले आहार के अनुकूल हो गए हैं। कथन 3 गलत है: सुंदरबन गंगा, ब्रह्मपुत्र और मेघना के डेल्टा पर हैं, जिसे भारत और बांग्लादेश साझा करते हैं; महानदी के डेल्टा में भितरकनिका है।','env-sundarbans-designations','original_pattern_matched','UNESCO World Heritage Centre -- Sundarbans National Park; Ramsar Sites Information Service -- Sundarban Wetland (2019); West Bengal Forest Department.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Dudhwa National Park is in Uttarakhand.", "Satpura National Park is in Chhattisgarh."], "statements_hi": ["दुधवा राष्ट्रीय उद्यान उत्तराखंड में है।", "सतपुड़ा राष्ट्रीय उद्यान छत्तीसगढ़ में है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. Dudhwa is in the terai of Lakhimpur Kheri district, Uttar Pradesh, on the Nepal border, and is known for its swamp deer and reintroduced rhinos. Satpura is in Madhya Pradesh, in the Satpura range around Pachmarhi, and is part of the Satpura Tiger Reserve.','कोई भी कथन सही नहीं है। दुधवा उत्तर प्रदेश के लखीमपुर खीरी ज़िले की तराई में नेपाल सीमा पर है, और अपने दलदली हिरणों और फिर से बसाए गए गैंडों के लिए जाना जाता है। सतपुड़ा मध्य प्रदेश में पचमढ़ी के आसपास सतपुड़ा पर्वतमाला में है, और सतपुड़ा बाघ अभयारण्य का भाग है।','env-dudhwa-satpura-location','original_pattern_matched','Uttar Pradesh Forest Department -- Dudhwa National Park; Madhya Pradesh Forest Department -- Satpura Tiger Reserve.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India is one of the world''s megadiverse countries.", "India has only about 2.4 per cent of the world''s land area but about 7 to 8 per cent of its recorded species."], "statements_hi": ["भारत विश्व के महाविविध (megadiverse) देशों में से एक है।", "भारत के पास विश्व के भू-क्षेत्र का केवल लगभग 2.4 प्रतिशत है, पर उसकी दर्ज प्रजातियों का लगभग 7 से 8 प्रतिशत है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. India is one of the 17 megadiverse countries identified by UNEP-WCMC, which together hold most of the world''s species. Its range of climates and landforms -- from the Himalaya and the Thar to the Western Ghats, the Sundarbans and the islands -- and its position where three biogeographic realms meet explain the richness, including many endemic species.','दोनों कथन सही हैं। भारत UNEP-WCMC द्वारा चिह्नित 17 महाविविध देशों में से एक है, जिनमें मिलकर विश्व की अधिकांश प्रजातियाँ हैं। हिमालय और थार से लेकर पश्चिमी घाट, सुंदरबन और द्वीपों तक जलवायु और भू-आकृतियों की विविधता, और तीन जैव-भौगोलिक क्षेत्रों के मिलन-स्थल पर इसकी स्थिति इस समृद्धि को, कई स्थानिक प्रजातियों सहित, समझाती है।','env-india-megadiverse','original_pattern_matched','NCERT Class XII, Biology -- Biodiversity and Conservation; UNEP World Conservation Monitoring Centre -- megadiverse countries.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Wildlife Week is observed in India in the first week of October.", "International Tiger Day is observed on 29 July.", "World Elephant Day is observed on 22 September."], "statements_hi": ["भारत में वन्यजीव सप्ताह अक्टूबर के पहले सप्ताह में मनाया जाता है।", "अंतरराष्ट्रीय बाघ दिवस 29 जुलाई को मनाया जाता है।", "विश्व हाथी दिवस 22 सितंबर को मनाया जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Wildlife Week runs from 2 to 8 October. International Tiger Day was set at the St Petersburg Tiger Summit in 2010, and India usually releases its tiger estimation results on or around it. Statement 3 is wrong: World Elephant Day, observed since 2012, falls on 12 August; 22 September is World Rhino Day.','कथन 1 और 2 सही हैं। वन्यजीव सप्ताह 2 से 8 अक्टूबर तक चलता है। अंतरराष्ट्रीय बाघ दिवस 2010 के सेंट पीटर्सबर्ग बाघ शिखर सम्मेलन में तय हुआ, और भारत प्रायः अपने बाघ आकलन के परिणाम इसी दिन या इसके आसपास जारी करता है। कथन 3 गलत है: 2012 से मनाया जाने वाला विश्व हाथी दिवस 12 अगस्त को पड़ता है; 22 सितंबर विश्व गैंडा दिवस है।','env-wildlife-days','original_pattern_matched','Ministry of Environment, Forest and Climate Change -- Wildlife Week and International Tiger Day; World Elephant Day.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements about environmental movements in India:','भारत के पर्यावरण आंदोलनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Chipko movement began in the Chamoli district of present-day Uttarakhand in 1973.", "The Appiko movement arose in Kerala.", "The Narmada Bachao Andolan was mainly a campaign against the Tehri dam."], "statements_hi": ["चिपको आंदोलन 1973 में वर्तमान उत्तराखंड के चमोली ज़िले में शुरू हुआ।", "अप्पिको आंदोलन केरल में उभरा।", "नर्मदा बचाओ आंदोलन मुख्य रूप से टिहरी बाँध के विरुद्ध एक अभियान था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: villagers, many of them women led by figures such as Gaura Devi, hugged trees to stop commercial felling around Mandal and Reni in Chamoli. Statement 2 is wrong: Appiko (''to hug'' in Kannada), inspired by Chipko, began in 1983 in the Uttara Kannada district of Karnataka. Statement 3 is wrong: the Narmada Bachao Andolan campaigned against the Sardar Sarovar and other Narmada dams over displacement; the opposition to the Tehri dam on the Bhagirathi was a separate movement led by Sunderlal Bahuguna.','केवल कथन 1 सही है: चमोली में मंडल और रैणी के आसपास व्यावसायिक कटाई रोकने के लिए ग्रामीणों ने, जिनमें गौरा देवी जैसी हस्तियों के नेतृत्व में अनेक महिलाएँ थीं, पेड़ों से लिपटकर विरोध किया। कथन 2 गलत है: चिपको से प्रेरित अप्पिको (कन्नड़ में ''गले लगाना'') 1983 में कर्नाटक के उत्तर कन्नड़ ज़िले में शुरू हुआ। कथन 3 गलत है: नर्मदा बचाओ आंदोलन ने विस्थापन के प्रश्न पर सरदार सरोवर और नर्मदा के दूसरे बाँधों के विरुद्ध अभियान चलाया; भागीरथी पर टिहरी बाँध का विरोध सुंदरलाल बहुगुणा के नेतृत्व में एक अलग आंदोलन था।','env-environmental-movements','original_pattern_matched','NCERT Class XII, Political Science -- Politics in India since Independence (Rise of Popular Movements); NCERT Class X, Contemporary India II -- Forest and Wildlife Resources.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Great Himalayan National Park is in Himachal Pradesh.", "Hemis National Park in Ladakh is known for its snow leopards.", "Namdapha National Park is in Sikkim."], "statements_hi": ["ग्रेट हिमालयन राष्ट्रीय उद्यान हिमाचल प्रदेश में है।", "लद्दाख का हेमिस राष्ट्रीय उद्यान अपने हिम तेंदुओं के लिए जाना जाता है।", "नामदफा राष्ट्रीय उद्यान सिक्किम में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Great Himalayan National Park in Kullu district is a UNESCO World Heritage Site (2014) for its western Himalayan biodiversity, and Hemis, India''s largest national park, is among the best places in the world to see snow leopards. Statement 3 is wrong: Namdapha is in Changlang district of Arunachal Pradesh, on the Myanmar border.','कथन 1 और 2 सही हैं। कुल्लू ज़िले का ग्रेट हिमालयन राष्ट्रीय उद्यान पश्चिमी हिमालय की जैव विविधता के लिए UNESCO विश्व धरोहर स्थल (2014) है, और भारत का सबसे बड़ा राष्ट्रीय उद्यान हेमिस हिम तेंदुए देखने के विश्व के सर्वश्रेष्ठ स्थानों में से है। कथन 3 गलत है: नामदफा म्यांमार सीमा पर अरुणाचल प्रदेश के चांगलांग ज़िले में है।','env-himalayan-national-parks','original_pattern_matched','UNESCO World Heritage Centre -- Great Himalayan National Park Conservation Area; Wildlife Institute of India, ENVIS Centre on Wildlife and Protected Areas -- National Wildlife Database.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','easy','Consider the following statements about Keoladeo National Park:','केवलादेव राष्ट्रीय उद्यान के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It was once a duck-shooting reserve of the Maharajas of Bharatpur.", "It is a UNESCO World Heritage Site.", "It is also known as the Ghana Bird Sanctuary."], "statements_hi": ["यह कभी भरतपुर के महाराजाओं का बत्तख-शिकार आरक्षित क्षेत्र था।", "यह एक UNESCO विश्व धरोहर स्थल है।", "इसे घना पक्षी विहार भी कहा जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Keoladeo is a man-made wetland: the rulers of Bharatpur built dykes and canals in the 19th century to flood the land for duck shoots. Declared a national park in 1982 and a World Heritage Site in 1985, it is one of the richest bird areas in Asia; its survival depends on water released from the Panchna dam and the Ajan bund, which is why it suffers in dry years. ''Ghana'' means dense, for its thick woodland.','तीनों कथन सही हैं। केवलादेव एक मानव-निर्मित आर्द्रभूमि है: भरतपुर के शासकों ने 19वीं सदी में बत्तखों के शिकार के लिए भूमि को डुबोने के लिए बाँध और नहरें बनाईं। 1982 में राष्ट्रीय उद्यान और 1985 में विश्व धरोहर स्थल घोषित यह एशिया के सबसे समृद्ध पक्षी क्षेत्रों में है; इसका अस्तित्व पांचना बाँध और अजान बाँध से छोड़े गए पानी पर निर्भर है, इसीलिए सूखे वर्षों में यह कष्ट में रहता है। ''घना'' का अर्थ है सघन, इसके घने वन के कारण।','env-keoladeo-history','original_pattern_matched','UNESCO World Heritage Centre -- Keoladeo National Park; Rajasthan Forest Department.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about the IUCN categories of protected areas:','संरक्षित क्षेत्रों की IUCN श्रेणियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Category Ia is a strict nature reserve.", "Category II is a national park.", "Category VI is a protected area with sustainable use of natural resources.", "The IUCN categories are legally binding on the countries that use them."], "statements_hi": ["श्रेणी Ia एक कठोर प्रकृति आरक्षित क्षेत्र (strict nature reserve) है।", "श्रेणी II एक राष्ट्रीय उद्यान है।", "श्रेणी VI प्राकृतिक संसाधनों के सतत उपयोग वाला संरक्षित क्षेत्र है।", "IUCN श्रेणियाँ उनका उपयोग करने वाले देशों पर कानूनी रूप से बाध्यकारी हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. The IUCN system runs from Ia (strict nature reserve) and Ib (wilderness area) through II (national park), III (natural monument), IV (habitat or species management area) and V (protected landscape or seascape) to VI (protected area with sustainable use), roughly from the strictest to the most open to human use. Statement 4 is wrong: the categories are a global standard for classifying and reporting, not law. Each country defines its own protected areas -- India''s national parks and sanctuaries are defined by the Wild Life (Protection) Act and are reported to the World Database on Protected Areas under the closest IUCN category.','कथन 1, 2 और 3 सही हैं। IUCN प्रणाली Ia (कठोर प्रकृति आरक्षित क्षेत्र) और Ib (वन्य क्षेत्र) से II (राष्ट्रीय उद्यान), III (प्राकृतिक स्मारक), IV (आवास या प्रजाति प्रबंधन क्षेत्र) और V (संरक्षित भू-दृश्य या समुद्र-दृश्य) होते हुए VI (सतत उपयोग वाला संरक्षित क्षेत्र) तक जाती है, मोटे तौर पर सबसे कठोर से मानव उपयोग के लिए सबसे खुले तक। कथन 4 गलत है: ये श्रेणियाँ वर्गीकरण और रिपोर्टिंग का वैश्विक मानक हैं, कानून नहीं। हर देश अपने संरक्षित क्षेत्र स्वयं परिभाषित करता है; भारत के राष्ट्रीय उद्यान और अभयारण्य वन्यजीव (संरक्षण) अधिनियम से परिभाषित हैं और निकटतम IUCN श्रेणी के तहत संरक्षित क्षेत्रों के विश्व डेटाबेस को बताए जाते हैं।','env-iucn-protected-area-categories','original_pattern_matched','IUCN -- Guidelines for Applying Protected Area Management Categories (2008); UNEP-WCMC -- World Database on Protected Areas.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about biodiversity hotspots:','जैव विविधता हॉटस्पॉट के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["To qualify as a hotspot, a region must have at least 1,500 endemic species of vascular plants and must have lost at least 70 per cent of its original habitat.", "India has parts of four hotspots: the Himalaya, Indo-Burma, the Western Ghats and Sri Lanka, and Sundaland.", "The Eastern Ghats form a separate biodiversity hotspot."], "statements_hi": ["हॉटस्पॉट होने के लिए किसी क्षेत्र में संवहनी पौधों की कम से कम 1,500 स्थानिक प्रजातियाँ होनी चाहिए और उसका कम से कम 70 प्रतिशत मूल आवास नष्ट हो चुका होना चाहिए।", "भारत में चार हॉटस्पॉट के भाग हैं: हिमालय, भारत-बर्मा, पश्चिमी घाट और श्रीलंका, तथा सुंडालैंड।", "पूर्वी घाट एक अलग जैव विविधता हॉटस्पॉट हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Norman Myers'' idea, adopted by Conservation International, combines two tests -- irreplaceability (many endemic plants) and threat (most of the habitat already gone) -- to pick out the places where conservation money saves the most species; the 36 hotspots cover only about 2.5 per cent of the Earth''s land but hold more than half of its plant species as endemics. India''s share of Sundaland is the Nicobar Islands. Statement 3 is wrong: the Eastern Ghats, though rich and threatened, are not a hotspot; the second criterion is what excludes many species-rich regions.','कथन 1 और 2 सही हैं। कंज़र्वेशन इंटरनेशनल द्वारा अपनाया गया नॉर्मन मायर्स का विचार दो कसौटियों को जोड़ता है, अपूरणीयता (बहुत से स्थानिक पौधे) और खतरा (अधिकांश आवास पहले ही नष्ट), ताकि वे स्थान चुने जा सकें जहाँ संरक्षण का पैसा सबसे अधिक प्रजातियाँ बचाता है; 36 हॉटस्पॉट पृथ्वी की भूमि का केवल लगभग 2.5 प्रतिशत हैं, पर उसकी आधी से अधिक पौधा-प्रजातियाँ स्थानिक रूप में इनमें हैं। सुंडालैंड में भारत का हिस्सा निकोबार द्वीपसमूह है। कथन 3 गलत है: समृद्ध और संकटग्रस्त होते हुए भी पूर्वी घाट हॉटस्पॉट नहीं हैं; दूसरी कसौटी ही कई प्रजाति-समृद्ध क्षेत्रों को बाहर कर देती है।','env-biodiversity-hotspots','original_pattern_matched','Conservation International -- Biodiversity Hotspots; N. Myers et al., Nature 403 (2000); NCERT Class XII, Biology -- Biodiversity and Conservation.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about the categories of the IUCN Red List:','IUCN रेड लिस्ट की श्रेणियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ''threatened'' categories are Critically Endangered, Endangered and Vulnerable.", "Near Threatened is one of the threatened categories.", "A species is classed as Extinct in the Wild when no living individual of it survives anywhere.", "A species classed as Data Deficient has been judged to be at no risk of extinction."], "statements_hi": ["''संकटग्रस्त'' (threatened) श्रेणियाँ गंभीर रूप से संकटग्रस्त, संकटग्रस्त और सुभेद्य हैं।", "निकट संकटग्रस्त (Near Threatened) संकटग्रस्त श्रेणियों में से एक है।", "किसी प्रजाति को ''वन में विलुप्त'' (Extinct in the Wild) तब माना जाता है जब उसका कोई भी जीवित सदस्य कहीं भी न बचा हो।", "आँकड़ा-अपर्याप्त (Data Deficient) श्रेणी की प्रजाति को विलुप्ति के किसी जोखिम से मुक्त माना गया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Critically Endangered, Endangered and Vulnerable together make up the ''threatened'' species. Statement 2 is wrong: Near Threatened species are close to qualifying but do not meet the thresholds, so they are not counted as threatened. Statement 3 describes Extinct, not Extinct in the Wild: an Extinct-in-the-Wild species survives only in cultivation, in captivity or as a naturalised population well outside its past range. Statement 4 is wrong: Data Deficient means there is too little information to assess the risk at all -- such species may well be threatened, which is why they are priorities for research.','केवल कथन 1 सही है: गंभीर रूप से संकटग्रस्त, संकटग्रस्त और सुभेद्य मिलकर ''संकटग्रस्त'' (threatened) प्रजातियाँ बनाते हैं। कथन 2 गलत है: निकट संकटग्रस्त प्रजातियाँ अर्हता के करीब हैं पर सीमाएँ पूरी नहीं करतीं, इसलिए उन्हें संकटग्रस्त नहीं गिना जाता। कथन 3 ''विलुप्त'' (Extinct) का वर्णन है, ''वन में विलुप्त'' का नहीं: वन में विलुप्त प्रजाति केवल खेती में, बंदी अवस्था में या अपने पुराने क्षेत्र से बहुत बाहर एक प्राकृतिक रूप से बसी आबादी के रूप में बचती है। कथन 4 गलत है: आँकड़ा-अपर्याप्त का अर्थ है कि जोखिम आँकने के लिए ही बहुत कम जानकारी है; ऐसी प्रजातियाँ संकटग्रस्त भी हो सकती हैं, इसीलिए वे शोध की प्राथमिकता हैं।','env-iucn-red-list-categories','original_pattern_matched','IUCN Red List of Threatened Species -- Categories and Criteria, version 3.1.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about the National Board for Wildlife:','राष्ट्रीय वन्यजीव बोर्ड (National Board for Wildlife) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is chaired by the Prime Minister.", "It was constituted under the Wild Life (Protection) Act by the amendment of 2002.", "Its Standing Committee, which considers proposals for projects in and around protected areas, is chaired by the Union Minister for Environment."], "statements_hi": ["इसकी अध्यक्षता प्रधानमंत्री करते हैं।", "इसका गठन वन्यजीव (संरक्षण) अधिनियम के तहत 2002 के संशोधन द्वारा किया गया।", "संरक्षित क्षेत्रों के भीतर और आसपास की परियोजनाओं के प्रस्तावों पर विचार करने वाली इसकी स्थायी समिति की अध्यक्षता केंद्रीय पर्यावरण मंत्री करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The NBWL, which replaced the older advisory Indian Board for Wildlife, is chaired by the Prime Minister, with the Environment Minister as vice-chairperson. In practice its Standing Committee, chaired by the Environment Minister, does most of the work: no alteration of the boundaries of a national park or sanctuary, and no project inside one, can go ahead without its approval. Its clearances for roads, mines and power lines in protected areas are often contested, which is why UPSC-style questions test who chairs which body.','तीनों कथन सही हैं। पुराने सलाहकार भारतीय वन्यजीव बोर्ड की जगह लेने वाले NBWL की अध्यक्षता प्रधानमंत्री करते हैं, और पर्यावरण मंत्री उपाध्यक्ष हैं। व्यवहार में अधिकांश काम पर्यावरण मंत्री की अध्यक्षता वाली इसकी स्थायी समिति करती है: किसी राष्ट्रीय उद्यान या अभयारण्य की सीमाओं में बदलाव, या उसके भीतर कोई परियोजना, इसकी स्वीकृति के बिना आगे नहीं बढ़ सकती। संरक्षित क्षेत्रों में सड़कों, खदानों और बिजली लाइनों के लिए इसकी स्वीकृतियाँ प्रायः विवादित रहती हैं, इसीलिए प्रश्न यह परखते हैं कि किस निकाय की अध्यक्षता कौन करता है।','env-national-board-for-wildlife','original_pattern_matched','Wild Life (Protection) Act, 1972, as amended in 2022, sections 5A to 5C and 35(5).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','statement_based','hard','Consider the following statements about marine protected areas in India:','भारत के समुद्री संरक्षित क्षेत्रों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Gulf of Mannar Marine National Park is in Tamil Nadu.", "The Gulf of Mannar Biosphere Reserve was the first marine biosphere reserve in South and South-East Asia.", "The Malvan Marine Sanctuary is in Maharashtra.", "The Mahatma Gandhi Marine National Park is in the Andaman and Nicobar Islands."], "statements_hi": ["मन्नार की खाड़ी समुद्री राष्ट्रीय उद्यान तमिलनाडु में है।", "मन्नार की खाड़ी जैवमंडल आरक्षित क्षेत्र दक्षिण और दक्षिण-पूर्व एशिया का पहला समुद्री जैवमंडल आरक्षित क्षेत्र था।", "मालवण समुद्री अभयारण्य महाराष्ट्र में है।", "महात्मा गांधी समुद्री राष्ट्रीय उद्यान अंडमान और निकोबार द्वीपसमूह में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The Gulf of Mannar park covers 21 small islands and their reefs between Rameswaram and Thoothukudi, and the biosphere reserve around it (1989) was the region''s first marine one; it shelters dugongs, sea turtles and seagrass beds. Malvan, on the Sindhudurg coast of Maharashtra, protects reefs and rocky shores, and the Mahatma Gandhi Marine National Park at Wandoor, near Port Blair, protects coral reefs and mangroves. A student who expects one statement in four to be false will fall for ''Only three''.','चारों कथन सही हैं। मन्नार की खाड़ी का उद्यान रामेश्वरम और थूथुकुडी के बीच 21 छोटे द्वीपों और उनकी भित्तियों को शामिल करता है, और उसके आसपास का जैवमंडल आरक्षित क्षेत्र (1989) इस क्षेत्र का पहला समुद्री आरक्षित क्षेत्र था; इसमें डुगोंग, समुद्री कछुए और समुद्री घास के मैदान हैं। महाराष्ट्र के सिंधुदुर्ग तट पर मालवण भित्तियों और चट्टानी तटों की रक्षा करता है, और पोर्ट ब्लेयर के पास वांडूर में महात्मा गांधी समुद्री राष्ट्रीय उद्यान प्रवाल भित्तियों और मैंग्रोव की रक्षा करता है। जो विद्यार्थी मानता है कि चार में से एक कथन गलत होगा ही, वह ''केवल तीन'' के जाल में फँसेगा।','env-marine-protected-areas','original_pattern_matched','Wildlife Institute of India, ENVIS Centre on Wildlife and Protected Areas -- National Wildlife Database (marine protected areas); UNESCO Man and the Biosphere Programme -- Gulf of Mannar Biosphere Reserve.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','The ''Hornbill Nest Adoption Programme'', in which local communities are paid to protect hornbill nests, began in:','''हॉर्नबिल नेस्ट एडॉप्शन प्रोग्राम'', जिसमें स्थानीय समुदायों को धनेश के घोंसलों की रक्षा के लिए भुगतान किया जाता है, कहाँ शुरू हुआ?','{}'::jsonb,'[{"id": "a", "body": "Periyar Tiger Reserve", "body_hi": "पेरियार बाघ अभयारण्य", "isCorrect": false}, {"id": "b", "body": "Kaziranga National Park", "body_hi": "काज़ीरंगा राष्ट्रीय उद्यान", "isCorrect": false}, {"id": "c", "body": "Pakke Tiger Reserve", "body_hi": "पक्के बाघ अभयारण्य", "isCorrect": true}, {"id": "d", "body": "Namdapha National Park", "body_hi": "नामदफा राष्ट्रीय उद्यान", "isCorrect": false}]'::jsonb,2,0.66,'The programme was started in 2011 around Pakke (Pakhui) Tiger Reserve in Arunachal Pradesh by the Nature Conservation Foundation, the State Forest Department and a local council of the Nyishi community, who had earlier hunted hornbills for their casques and meat. Villagers are paid to find and guard nests, which has turned former hunters into protectors. Namdapha is also in Arunachal and has hornbills, which makes it the closest distractor.','यह कार्यक्रम 2011 में अरुणाचल प्रदेश के पक्के (पाखुई) बाघ अभयारण्य के आसपास नेचर कंज़र्वेशन फ़ाउंडेशन, राज्य वन विभाग और न्यीशी समुदाय की एक स्थानीय परिषद ने शुरू किया, जो पहले धनेशों का उनकी चोंच-टोपी (casque) और मांस के लिए शिकार करते थे। ग्रामीणों को घोंसले ढूँढ़ने और उनकी रखवाली के लिए भुगतान मिलता है, जिसने पुराने शिकारियों को रक्षक बना दिया है। नामदफा भी अरुणाचल में है और वहाँ भी धनेश हैं, इसलिए वह सबसे निकट का गलत विकल्प है।','env-hornbill-nest-adoption-pakke','original_pattern_matched','Nature Conservation Foundation -- Hornbill Nest Adoption Programme; Arunachal Pradesh Forest Department -- Pakke Tiger Reserve.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','Which one of the following is listed as Critically Endangered on the IUCN Red List?','निम्नलिखित में से कौन-सा IUCN रेड लिस्ट में गंभीर रूप से संकटग्रस्त (Critically Endangered) के रूप में सूचीबद्ध है?','{}'::jsonb,'[{"id": "a", "body": "Jerdon''s courser", "body_hi": "जर्डन्स कोर्सर", "isCorrect": true}, {"id": "b", "body": "Snow leopard", "body_hi": "हिम तेंदुआ", "isCorrect": false}, {"id": "c", "body": "Asiatic lion", "body_hi": "एशियाई शेर", "isCorrect": false}, {"id": "d", "body": "Greater one-horned rhinoceros", "body_hi": "एक सींग वाला बड़ा गैंडा", "isCorrect": false}]'::jsonb,2,0.66,'Jerdon''s courser, a nocturnal bird of the scrub jungles of Andhra Pradesh, was thought extinct until it was rediscovered in 1986 near Lankamalai; it is Critically Endangered, and a canal and road through its habitat in the Sri Lankamalleswara sanctuary became a test case for conservation. The snow leopard and the one-horned rhinoceros are Vulnerable, and the Asiatic lion is assessed as Endangered -- famous animals whose categories students often overestimate.','आंध्र प्रदेश के झाड़ीदार जंगलों का रात्रिचर पक्षी जर्डन्स कोर्सर तब तक विलुप्त माना जाता था जब तक 1986 में लंकमलाई के पास इसकी फिर से खोज नहीं हुई; यह गंभीर रूप से संकटग्रस्त है, और श्री लंकमल्लेश्वर अभयारण्य में इसके आवास से गुज़रने वाली नहर और सड़क संरक्षण का एक परीक्षण-मामला बनी। हिम तेंदुआ और एक सींग वाला गैंडा सुभेद्य हैं, और एशियाई शेर संकटग्रस्त आँका गया है; ये प्रसिद्ध जीव हैं जिनकी श्रेणी को विद्यार्थी प्रायः बढ़ा-चढ़ाकर आँकते हैं।','env-jerdons-courser-cr','original_pattern_matched','IUCN Red List of Threatened Species: Rhinoptilus bitorquatus, Panthera uncia, Panthera leo persica, Rhinoceros unicornis; Bombay Natural History Society -- Jerdon''s courser.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','The ''Nagar Van Yojana'' aims to:','''नगर वन योजना'' का लक्ष्य है:','{}'::jsonb,'[{"id": "a", "body": "Plant mangroves along India''s coasts and salt pans", "body_hi": "भारत के तटों और नमक के खेतों पर मैंग्रोव लगाना", "isCorrect": false}, {"id": "b", "body": "Restore the degraded Aravalli ranges across four States", "body_hi": "चार राज्यों में फैली क्षरित अरावली पर्वतमाला को पुनर्स्थापित करना", "isCorrect": false}, {"id": "c", "body": "Give sacred groves the status of reserved forests", "body_hi": "पवित्र उपवनों को आरक्षित वन का दर्जा देना", "isCorrect": false}, {"id": "d", "body": "Develop urban forests in cities", "body_hi": "शहरों में शहरी वन विकसित करना", "isCorrect": true}]'::jsonb,2,0.66,'The Nagar Van Yojana, launched on World Environment Day 2020, funds urban forests (Nagar Vans) and school nurseries in towns and cities, mainly through CAMPA funds, to improve green cover, cool the city and give residents a place close to nature; the target was later raised to 1,000 Nagar Vans. The distractors are real schemes: mangrove planting is MISHTI, and the Aravalli Green Wall Project (2023) aims to restore a green belt across Gujarat, Rajasthan, Haryana and Delhi.','विश्व पर्यावरण दिवस 2020 पर शुरू हुई नगर वन योजना कस्बों और शहरों में शहरी वनों (नगर वनों) और स्कूल पौधशालाओं को मुख्यतः CAMPA निधि से धन देती है, ताकि हरित आवरण बढ़े, शहर ठंडा हो और निवासियों को प्रकृति के पास एक स्थान मिले; बाद में लक्ष्य बढ़ाकर 1,000 नगर वन किया गया। गलत विकल्प असली योजनाएँ हैं: मैंग्रोव रोपण MISHTI है, और अरावली ग्रीन वॉल परियोजना (2023) का लक्ष्य गुजरात, राजस्थान, हरियाणा और दिल्ली में एक हरित पट्टी पुनर्स्थापित करना है।','env-nagar-van-yojana','original_pattern_matched','Ministry of Environment, Forest and Climate Change -- Nagar Van Yojana (2020); Aravalli Green Wall Project (2023).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','medium','The Soliga people became, in 2011, the first community living inside a tiger reserve to have their forest rights formally recognised. The tiger reserve is:','सोलिगा लोग 2011 में किसी बाघ अभयारण्य के भीतर रहने वाला पहला समुदाय बने, जिनके वन अधिकारों को औपचारिक मान्यता मिली। यह बाघ अभयारण्य है:','{}'::jsonb,'[{"id": "a", "body": "Sariska Tiger Reserve, Rajasthan", "body_hi": "सरिस्का बाघ अभयारण्य, राजस्थान", "isCorrect": false}, {"id": "b", "body": "BRT Tiger Reserve, Karnataka", "body_hi": "BRT (बिलिगिरि रंगनाथ मंदिर) बाघ अभयारण्य, कर्नाटक", "isCorrect": true}, {"id": "c", "body": "Tadoba-Andhari Tiger Reserve, Maharashtra", "body_hi": "ताडोबा-अंधारी बाघ अभयारण्य, महाराष्ट्र", "isCorrect": false}, {"id": "d", "body": "Pench Tiger Reserve, Madhya Pradesh", "body_hi": "पेंच बाघ अभयारण्य, मध्य प्रदेश", "isCorrect": false}]'::jsonb,2,0.66,'The Soligas of the Biligiri Rangaswamy (BRT) hills in Karnataka received community forest rights under the Forest Rights Act, 2006, while remaining inside the tiger reserve -- evidence often cited that conservation and people''s rights need not be opposed. Tiger numbers in BRT rose in the years that followed. In Sariska, Tadoba and Pench the emphasis has instead been on voluntary relocation of villages from core areas.','कर्नाटक की बिलिगिरि रंगास्वामी (BRT) पहाड़ियों के सोलिगा लोगों को बाघ अभयारण्य के भीतर रहते हुए वन अधिकार अधिनियम, 2006 के तहत सामुदायिक वन अधिकार मिले; इसे प्रायः इस बात के प्रमाण के रूप में उद्धृत किया जाता है कि संरक्षण और लोगों के अधिकार विरोधी नहीं होने चाहिए। बाद के वर्षों में BRT में बाघों की संख्या बढ़ी। सरिस्का, ताडोबा और पेंच में इसके बजाय ज़ोर कोर क्षेत्रों से गाँवों के स्वैच्छिक स्थानांतरण पर रहा है।','env-soliga-brt-forest-rights','original_pattern_matched','Ministry of Tribal Affairs -- Forest Rights Act, 2006 (community forest resource rights); Karnataka Forest Department -- BRT Tiger Reserve.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','easy','Who among the following was the first Director of Project Tiger and is often called the ''Tiger Man of India''?','निम्नलिखित में से कौन प्रोजेक्ट टाइगर के पहले निदेशक थे और जिन्हें प्रायः ''भारत का टाइगर मैन'' कहा जाता है?','{}'::jsonb,'[{"id": "a", "body": "Salim Ali", "body_hi": "सलीम अली", "isCorrect": false}, {"id": "b", "body": "Jim Corbett", "body_hi": "जिम कॉर्बेट", "isCorrect": false}, {"id": "c", "body": "Kailash Sankhala", "body_hi": "कैलाश सांखला", "isCorrect": true}, {"id": "d", "body": "Billy Arjan Singh", "body_hi": "बिली अर्जन सिंह", "isCorrect": false}]'::jsonb,2,0.66,'Kailash Sankhala, a forester from Rajasthan, led Project Tiger from its launch in 1973 and wrote ''Tiger!''. Salim Ali is remembered as the ''Birdman of India''; Jim Corbett was a hunter-turned-conservationist after whom India''s first national park is named; and Billy Arjan Singh campaigned for the creation of Dudhwa National Park and hand-reared tigers and leopards there.','राजस्थान के वनाधिकारी कैलाश सांखला ने 1973 में इसके शुरू होने से प्रोजेक्ट टाइगर का नेतृत्व किया और ''Tiger!'' पुस्तक लिखी। सलीम अली को ''भारत के पक्षी-पुरुष'' के रूप में याद किया जाता है; जिम कॉर्बेट शिकारी से संरक्षणवादी बने, जिनके नाम पर भारत का पहला राष्ट्रीय उद्यान है; और बिली अर्जन सिंह ने दुधवा राष्ट्रीय उद्यान बनवाने के लिए अभियान चलाया और वहाँ बाघों और तेंदुओं को पाल-पोसकर जंगल में छोड़ा।','env-kailash-sankhala','original_pattern_matched','National Tiger Conservation Authority -- history of Project Tiger; K. Sankhala, Tiger! (1978).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','hard','Arrange the following tiger reserves from north to south:','निम्नलिखित बाघ अभयारण्यों को उत्तर से दक्षिण के क्रम में व्यवस्थित कीजिए:','{"statements": ["Palamau", "Panna", "Achanakmar", "Tadoba-Andhari"], "statements_hi": ["पलामू", "पन्ना", "अचानकमार", "ताडोबा-अंधारी"], "closing": "Select the correct order using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही क्रम चुनिए:"}'::jsonb,'[{"id": "a", "body": "1-2-3-4", "body_hi": "1-2-3-4", "isCorrect": false}, {"id": "b", "body": "2-1-3-4", "body_hi": "2-1-3-4", "isCorrect": true}, {"id": "c", "body": "2-1-4-3", "body_hi": "2-1-4-3", "isCorrect": false}, {"id": "d", "body": "1-2-4-3", "body_hi": "1-2-4-3", "isCorrect": false}]'::jsonb,2,0.66,'The order is Panna (Madhya Pradesh, about 24.5 degrees N), Palamau (Jharkhand, about 23.8 degrees N), Achanakmar (Chhattisgarh, about 22.5 degrees N) and Tadoba-Andhari (Maharashtra, about 20.2 degrees N). The hard part is the first pair: Palamau, in Jharkhand, feels as if it should lie further north than Panna, but Panna sits on the Vindhyan plateau near the Uttar Pradesh border and is the northernmost of the four. Achanakmar is linked by forest to Kanha, and Tadoba to the forests of Telangana.','क्रम है: पन्ना (मध्य प्रदेश, लगभग 24.5 डिग्री उ.), पलामू (झारखंड, लगभग 23.8 डिग्री उ.), अचानकमार (छत्तीसगढ़, लगभग 22.5 डिग्री उ.) और ताडोबा-अंधारी (महाराष्ट्र, लगभग 20.2 डिग्री उ.)। कठिन भाग पहली जोड़ी है: झारखंड का पलामू पन्ना से अधिक उत्तर में लगता है, पर पन्ना उत्तर प्रदेश की सीमा के पास विंध्य पठार पर है और चारों में सबसे उत्तरी है। अचानकमार वनों के ज़रिए कान्हा से जुड़ा है, और ताडोबा तेलंगाना के वनों से।','env-tiger-reserves-north-south','original_pattern_matched','National Tiger Conservation Authority -- tiger reserves of India (locations); Survey of India maps.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','mcq','hard','The Terai Arc Landscape, a transboundary conservation landscape for tigers, rhinos and elephants, spans:','बाघों, गैंडों और हाथियों के लिए सीमा-पार संरक्षण भू-दृश्य ''तराई आर्क लैंडस्केप'' किन देशों में फैला है?','{}'::jsonb,'[{"id": "a", "body": "India and Nepal", "body_hi": "भारत और नेपाल", "isCorrect": true}, {"id": "b", "body": "India and Bhutan", "body_hi": "भारत और भूटान", "isCorrect": false}, {"id": "c", "body": "India, Nepal and Bhutan", "body_hi": "भारत, नेपाल और भूटान", "isCorrect": false}, {"id": "d", "body": "India and Bangladesh", "body_hi": "भारत और बांग्लादेश", "isCorrect": false}]'::jsonb,2,0.66,'The Terai Arc Landscape stretches along the Himalayan foothills from the Yamuna in the west to the Bagmati in the east, across Uttarakhand, Uttar Pradesh and Bihar in India and the terai of Nepal. It links protected areas such as Rajaji, Corbett, Dudhwa and Valmiki with Nepal''s Shuklaphanta, Bardia, Banke, Chitwan and Parsa, so that tigers and elephants can move between them. Bhutan is the trap: it is part of other transboundary landscapes, such as Manas with Royal Manas, but not the Terai Arc.','तराई आर्क लैंडस्केप हिमालय की तलहटी में पश्चिम में यमुना से पूर्व में बागमती तक, भारत में उत्तराखंड, उत्तर प्रदेश और बिहार तथा नेपाल की तराई में फैला है। यह राजाजी, कॉर्बेट, दुधवा और वाल्मीकि जैसे संरक्षित क्षेत्रों को नेपाल के शुक्लाफांटा, बर्दिया, बांके, चितवन और पर्सा से जोड़ता है, ताकि बाघ और हाथी उनके बीच आ-जा सकें। भूटान जाल है: वह दूसरे सीमा-पार भू-दृश्यों का हिस्सा है, जैसे रॉयल मानस के साथ मानस, पर तराई आर्क का नहीं।','env-terai-arc-landscape','original_pattern_matched','WWF-India -- Terai Arc Landscape; National Tiger Conservation Authority -- tiger landscapes.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Wildlife corridors are important for the long-term survival of tigers.", "assertion_hi": "वन्यजीव गलियारे (wildlife corridors) बाघों के दीर्घकालिक अस्तित्व के लिए महत्त्वपूर्ण हैं।", "reason": "Corridors allow movement and gene flow between populations that would otherwise be isolated.", "reason_hi": "गलियारे उन आबादियों के बीच आवागमन और जीन-प्रवाह होने देते हैं जो अन्यथा अलग-थलग रह जातीं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Most tiger reserves are too small to hold a population that can stay genetically healthy on its own; young tigers dispersing through forest corridors -- such as those linking Kanha and Pench or Tadoba and the Telangana forests -- carry genes between reserves and prevent inbreeding. That is why highways through corridors now have to include animal underpasses, as on NH-44 through the Pench landscape.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। अधिकांश बाघ अभयारण्य इतने छोटे हैं कि वे अकेले आनुवंशिक रूप से स्वस्थ आबादी नहीं रख सकते; वन गलियारों से फैलते युवा बाघ, जैसे कान्हा और पेंच या ताडोबा और तेलंगाना के वनों को जोड़ने वाले गलियारों से, अभयारण्यों के बीच जीन ले जाते हैं और अंतःप्रजनन रोकते हैं। इसीलिए गलियारों से गुज़रने वाले राजमार्गों में अब जंतुओं के लिए अंडरपास बनाने पड़ते हैं, जैसे पेंच भू-दृश्य से गुज़रते NH-44 पर।','env-tiger-corridors-gene-flow','original_pattern_matched','National Tiger Conservation Authority and Wildlife Institute of India -- Connecting Tiger Populations for Long-term Conservation (2014); Eco-friendly Measures to Mitigate Impacts of Linear Infrastructure on Wildlife (2016).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Villages have been relocated from the core areas of several tiger reserves.", "assertion_hi": "कई बाघ अभयारण्यों के कोर क्षेत्रों से गाँवों को स्थानांतरित किया गया है।", "reason": "The Wild Life (Protection) Act allows people to be relocated from a tiger reserve without their consent whenever the National Tiger Conservation Authority so decides.", "reason_hi": "वन्यजीव (संरक्षण) अधिनियम राष्ट्रीय बाघ संरक्षण प्राधिकरण के निर्णय पर लोगों को उनकी सहमति के बिना बाघ अभयारण्य से स्थानांतरित करने की अनुमति देता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct: villages have moved out of the cores of reserves such as Kanha, Sariska and Tadoba, with compensation packages, to create inviolate areas for tigers. Statement-II is incorrect: section 38V(5) of the Wild Life (Protection) Act requires that relocation from a tiger reserve be voluntary, on mutually agreed terms, with a rehabilitation package that provides for livelihoods, and only after the rights of the people have been settled. The Forest Rights Act adds that people can be moved out of ''critical wildlife habitats'' only if coexistence is shown to be impossible and they give free, informed consent.','कथन-I सही है: बाघों के लिए अक्षुण्ण क्षेत्र बनाने के लिए कान्हा, सरिस्का और ताडोबा जैसे अभयारण्यों के कोर से गाँव मुआवज़ा पैकेज के साथ बाहर गए हैं। कथन-II गलत है: वन्यजीव (संरक्षण) अधिनियम की धारा 38V(5) अपेक्षा करती है कि बाघ अभयारण्य से स्थानांतरण स्वैच्छिक हो, परस्पर सहमत शर्तों पर हो, आजीविका की व्यवस्था वाला पुनर्वास पैकेज हो, और लोगों के अधिकार तय होने के बाद ही हो। वन अधिकार अधिनियम इसमें जोड़ता है कि ''महत्त्वपूर्ण वन्यजीव आवासों'' से लोगों को तभी हटाया जा सकता है जब सह-अस्तित्व असंभव सिद्ध हो और वे स्वतंत्र, सूचित सहमति दें।','env-tiger-reserve-relocation-fra','original_pattern_matched','Scheduled Tribes and Other Traditional Forest Dwellers (Recognition of Forest Rights) Act, 2006, section 4(2); Wild Life (Protection) Act, 1972, as amended in 2022, section 38V(5).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The cheetah became extinct in India in the mid-twentieth century.", "assertion_hi": "चीता बीसवीं सदी के मध्य में भारत में विलुप्त हो गया।", "reason": "Hunting, including the capture of wild cheetahs to be trained for coursing by royalty, depleted their numbers.", "reason_hi": "शिकार ने, जिसमें राजघरानों द्वारा शिकार-दौड़ (coursing) के लिए प्रशिक्षित करने हेतु जंगली चीतों को पकड़ना भी शामिल था, उनकी संख्या घटा दी।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "Open grasslands and scrub, their habitat, were turned into farmland, and their prey declined.", "reason_2_hi": "उनके आवास, खुले घास के मैदान और झाड़ियाँ, खेतों में बदल गए, और उनका शिकार घटता गया।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": true}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Both Statement II and Statement III are correct, and both explain Statement I. For centuries Indian rulers caught adult cheetahs from the wild to train them for hunting blackbuck, and cheetahs rarely bred in captivity, so each captured animal was a loss to the wild; bounty hunting and sport shooting added to it. At the same time the open grasslands and scrub they depend on were turned into farmland, and their prey, blackbuck and chinkara, declined. The cheetah was declared extinct in India in 1952 -- the only large mammal India is known to have lost since Independence.','कथन-II और कथन-III दोनों सही हैं, और दोनों कथन-I की व्याख्या करते हैं। सदियों तक भारतीय शासक काले हिरण के शिकार के लिए प्रशिक्षित करने हेतु जंगल से वयस्क चीते पकड़ते रहे, और चीते बंदी अवस्था में शायद ही प्रजनन करते थे, इसलिए हर पकड़ा गया चीता जंगल की हानि था; इनाम के लिए शिकार और खेल-शिकार ने इसे और बढ़ाया। साथ ही, जिन खुले घास के मैदानों और झाड़ियों पर वे निर्भर थे वे खेतों में बदल गए, और उनके शिकार, काला हिरण और चिंकारा, घटते गए। चीते को 1952 में भारत में विलुप्त घोषित किया गया; यह स्वतंत्रता के बाद भारत में लुप्त हुआ एकमात्र बड़ा स्तनधारी माना जाता है।','env-cheetah-extinction-india','original_pattern_matched','M.K. Ranjitsinh and Y.V. Jhala, Assessing the Potential for Reintroducing the Cheetah in India (Wildlife Trust of India / Wildlife Institute of India, 2010); MoEFCC -- Action Plan for Introduction of Cheetah in India (2022).','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','match_the_following','easy','Consider the following pairs of national parks and States:','राष्ट्रीय उद्यानों और राज्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Bandhavgarh", "2. Sariska", "3. Nagarhole", "4. Valmiki"], "list_1_hi": ["1. बांधवगढ़", "2. सरिस्का", "3. नागरहोल", "4. वाल्मीकि"], "list_2": ["Madhya Pradesh", "Rajasthan", "Kerala", "Bihar"], "list_2_hi": ["मध्य प्रदेश", "राजस्थान", "केरल", "बिहार"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. Bandhavgarh (Madhya Pradesh) has one of the highest densities of tigers in India; Sariska (Rajasthan) lost all its tigers to poaching by 2005 and was restocked from Ranthambore; and Valmiki, in West Champaran, is Bihar''s only tiger reserve, adjoining Chitwan in Nepal. Pair 3 is wrong: Nagarhole (Rajiv Gandhi National Park) is in Karnataka, though it borders Wayanad in Kerala as part of the Nilgiri landscape.','तीन युग्म सही हैं। बांधवगढ़ (मध्य प्रदेश) में भारत में बाघों का घनत्व सबसे अधिक में से एक है; सरिस्का (राजस्थान) ने 2005 तक शिकार के कारण अपने सारे बाघ खो दिए और रणथंभौर से फिर बसाया गया; और पश्चिम चंपारण का वाल्मीकि बिहार का एकमात्र बाघ अभयारण्य है, जो नेपाल के चितवन से सटा है। युग्म 3 गलत है: नागरहोल (राजीव गांधी राष्ट्रीय उद्यान) कर्नाटक में है, हालाँकि नीलगिरि भू-दृश्य के भाग के रूप में यह केरल के वायनाड से सटा है।','env-national-parks-states-pairs','original_pattern_matched','National Tiger Conservation Authority -- tiger reserves of India; State Forest Departments.','draft'),
('upsc','Environment & Ecology','Protected Areas & Wildlife Protection','match_the_following','medium','Consider the following pairs of protected areas and the species they are best known for:','संरक्षित क्षेत्रों और उन प्रजातियों के निम्नलिखित युग्मों पर विचार कीजिए जिनके लिए वे सबसे अधिक जाने जाते हैं:','{"list_1": ["1. Velavadar", "2. Rollapadu", "3. Dibru-Saikhowa", "4. Eravikulam"], "list_1_hi": ["1. वेलावदर", "2. रोल्लापाडु", "3. डिब्रू-सैखोवा", "4. एराविकुलम"], "list_2": ["Blackbuck", "Hangul", "Feral horses", "Asiatic lion"], "list_2_hi": ["काला हिरण", "हंगुल", "जंगली घोड़े (feral horses)", "एशियाई शेर"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 3 are correct. Velavadar, on the grasslands of Bhavnagar in Gujarat, is the Blackbuck National Park. Dibru-Saikhowa in Assam, on the Brahmaputra floodplain, is known for its feral horses -- descendants of army horses left behind after the Second World War -- as well as white-winged wood ducks. Pair 2 is wrong: Rollapadu in Andhra Pradesh is a sanctuary for the Great Indian Bustard; the hangul, the Kashmir stag, lives in Dachigam. Pair 4 is wrong: Eravikulam in Kerala is the stronghold of the Nilgiri tahr.','केवल युग्म 1 और 3 सही हैं। गुजरात के भावनगर के घास के मैदानों पर वेलावदर काला हिरण राष्ट्रीय उद्यान है। ब्रह्मपुत्र के बाढ़-मैदान पर असम का डिब्रू-सैखोवा अपने जंगली घोड़ों के लिए, जो द्वितीय विश्वयुद्ध के बाद छोड़े गए सेना के घोड़ों के वंशज हैं, और सफ़ेद पंखों वाली वन-बतख के लिए जाना जाता है। युग्म 2 गलत है: आंध्र प्रदेश का रोल्लापाडु सोन चिरैया (Great Indian Bustard) का अभयारण्य है; कश्मीरी बारहसिंगा हंगुल दाचीगाम में रहता है। युग्म 4 गलत है: केरल का एराविकुलम नीलगिरि तहर का गढ़ है।','env-protected-areas-species-pairs','original_pattern_matched','Wildlife Institute of India, ENVIS Centre on Wildlife and Protected Areas -- National Wildlife Database; State Forest Departments of Gujarat, Andhra Pradesh, Assam and Kerala.','draft')
